def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    # Check odd divisors up to sqrt(n)
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def calculate_primes(start, end):
    """Calculate all prime numbers in a given range."""
    primes = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)
    return primes

if __name__ == "__main__":
    # Calculate primes from 1 to 50
    print("Prime Numbers from 1 to 50:")
    print("-" * 30)

    primes = calculate_primes(1, 50)

    # Print each prime number
    for prime in primes:
        print(prime)

    # Show the total count
    print("-" * 30)
    print(f"Total count: {len(primes)} prime numbers")

